"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { pressedWash } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Playful console Toggle: a small key that holds its state. Off, it is a
 * bare label that takes a cream wash on hover, or a white chip with an olive
 * edge. Pressed, it takes the orange wash behind the orange rim.
 */
const toggleVariants = cva(
  [
    "inline-flex shrink-0 select-none items-center justify-center gap-1.5 whitespace-nowrap rounded-md border border-transparent",
    "font-semibold text-(--foreground-secondary)",
    "transition-[background-color,border-color,color] duration-fast ease-out",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
    "data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
    pressedWash,
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-transparent hover:not-data-[pressed]:bg-secondary hover:not-data-[pressed]:text-foreground",
        outline:
          "border-(--line-strong) bg-card hover:not-data-[pressed]:bg-secondary data-[disabled]:border-border data-[disabled]:bg-secondary",
      },
      size: {
        sm: "h-7 px-2.5 text-xs",
        default: "h-8 px-3 text-sm",
        lg: "h-10 px-4 text-sm",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/** A single pressable toggle; pass `variant` and `size` from toggleVariants. */
const Toggle = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TogglePrimitive.Props> & VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive
    ref={ref}
    data-slot="toggle"
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
));
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
